// Automatically register all loaded keys into ALL_PIECE_KEYS
(function() {
  const scope = (typeof window !== 'undefined' ? window : globalThis);
  if (!scope.ALL_PIECE_KEYS) scope.ALL_PIECE_KEYS = [];
  const keys = Object.keys(scope.PIECES);
  for (let i = 0; i < keys.length; i++) {
    if (!scope.ALL_PIECE_KEYS.includes(keys[i])) {
      scope.ALL_PIECE_KEYS.push(keys[i]);
    }
  }
  if (typeof module !== 'undefined' && module.exports) {
    module.exports = scope.PIECES;
  }
})();
